using System.Collections.Generic;

namespace VikingVillages
{
	internal static partial class VikingNewsLines
	{
		/// <summary>
		/// What a viking says about the player mastering a skill, mastering every skill, and earning one of the game's
		/// achievements, by its pool
		/// </summary>
		private static readonly Dictionary<string, string[]> FeatPools = new Dictionary<string, string[]>
		{
			{ "skill/Swords", new[] { "No blade in all the land sings like yours, {player}. A true sword master!", "They say even Odin's einherjar would come to you for lessons.", "Word is you can cut a falling leaf in two. Is it true?", "Steel bends to your will now. Remind me never to spar with you." } },
			{ "skill/Knives", new[] { "They say your knife finds the gap in any armor, {player}.", "Word is you strike from behind before they even know you're there. Sneaky, and brilliant.", "Such a small blade for such a big reputation! Well done.", "A master of the knife! I'll be careful carving the meat while you're watching, {player}." } },
			{ "skill/Clubs", new[] { "Word is you can flatten a troll with one swing of a club, {player}.", "A master of the club! Simple, honest work - hit it until it stops.", "No fancy edges for you, just good heavy wood and iron. And now you're the best there is.", "They say the ground shakes when you bring a sledge down, {player}. I believe it." } },
			{ "skill/Polearms", new[] { "They say you sweep a whole pack off its feet with one swing of your atgeir.", "A master of the polearm! Keeping enemies at arm's length - and then some.", "{player}, word is you spin that atgeir like a whirlwind. Stand back, everyone!", "Long reach and an even longer reputation. Well done, master of the polearm." } },
			{ "skill/Spears", new[] { "They say your thrown spear never misses, {player}. Not once.", "Strike, throw, fetch it back, strike again - you make the spear look easy.", "Even the boars have heard of your spear. They run when they see you coming.", "Odin's own Gungnir would be proud to fly from your hand, {player}." } },
			{ "skill/Blocking", new[] { "They say nothing gets past your shield anymore, {player}.", "A master of the shield! A troll's club just bounces off you, I hear.", "Word is you parry so well your enemies knock themselves off balance.", "Best shield in the land, they say. Stand in front of me next raid, will you, {player}?" } },
			{ "skill/Axes", new[] { "Every Viking carries an axe, but only you have truly mastered one, {player}.", "They say you can split a shield clean in two with one swing. Mighty work!", "There's no more honest weapon than an axe, and nobody swings one better than you.", "Word is the trolls step aside when they see your axe coming." } },
			{ "skill/Bows", new[] { "They say you can hit a deer's eye from across the meadow, {player}.", "A master archer! Ullr himself would want to shoot beside you.", "Word is your arrows land before your enemies even know you're there.", "Draw, loose, and down it goes. They say you never miss a moving target, {player}." } },
			{ "skill/ElementalMagic", new[] { "Fire, frost and lightning all answer your staff now, {player}. Remarkable!", "A master of the elements! Just... keep the fire away from the thatch, please.", "They say you call down lightning like Thor himself. Is it true?", "Word is you brought a blizzard to a sword fight. And won!" } },
			{ "skill/BloodMagic", new[] { "They say you pay your staff in blood and it never fails you. Brave, {player}.", "Your staff mends wounds faster than any healer's herbs, I hear. Come by next time I cut myself!", "Word is no one shields a war band like you do. Your friends must sleep easy.", "Giving your own blood so others don't bleed - that's what mastery looks like." } },
			{ "skill/Unarmed", new[] { "They say you knocked a troll flat with your bare fists, {player}. Is that true?", "A master of the fists! Who needs a sword when your knuckles are that hard?", "Word is you wrestle boars for fun now. Remind me never to arm-wrestle you.", "No weapon, no shield, no trouble. Now that's a real Viking brawler." } },
			{ "skill/Pickaxes", new[] { "They say you could dig through a mountain in a day, {player}.", "A master miner! Copper, tin, iron, silver - the earth gives it all up for you.", "Word is the rocks crack before your pickaxe even touches them.", "The smiths must love you - you bring them more ore than they can smelt." } },
			{ "skill/WoodCutting", new[] { "They say the trees tremble when you walk into a forest, {player}.", "Half the halls in the land must be built from your timber. Fine work!", "Word is you fell an old oak in three swings. It takes me thirty.", "Timber! You must shout that in your sleep by now. A true master of the woods." } },
			{ "skill/Crossbows", new[] { "They say your bolts punch through a troll's hide like cloth, {player}.", "A master of the crossbow! Slow to load, but you never need a second shot.", "Word is you reload faster than most of us can draw a bow.", "That crossbow has found its master, {player}. The dvergr would be impressed." } },
			{ "skill/Jump", new[] { "They say you can leap a fence without breaking stride, {player}.", "A master jumper! Are you sure you're not part goat, {player}?", "Word is you jumped clear across a river. Odin's ravens were jealous.", "Up cliffs and over walls - nothing's too high for you now." } },
			{ "skill/Sneak", new[] { "They say you can walk right past a sleeping troll without waking it, {player}.", "A master of sneaking! Then again... how long have you been standing there, {player}?", "Word is the deer don't hear you until you're close enough to pat them.", "Quiet as a shadow in the woods. Even the Greydwarves never see you coming." } },
			{ "skill/Run", new[] { "They say you can outrun a boar, a wolf and the weather, {player}.", "A master runner! The news of it barely beat you here, {player}.", "Word is you cross the whole meadow without stopping for breath.", "Fast feet and endless breath! Even Hermod, swiftest of the gods, would race you." } },
			{ "skill/Swim", new[] { "They say you swim like a seal now, {player}.", "A master swimmer! If our boat ever sinks, I'm swimming next to you.", "Word is you crossed a whole channel without a boat. Mad, and magnificent.", "Njord must be proud - you're as much at home in the water as on land." } },
			{ "skill/Fishing", new[] { "They say the fish jump onto your hook just to meet you, {player}.", "A master angler! Patience like yours is rarer than silver.", "Word is you can tell what's biting just from the twitch of the line.", "No one in the land hauls in a catch like you. Save us a few for the fire!" } },
			{ "skill/Cooking", new[] { "They say your stew could make a troll weep with joy, {player}.", "A master cook! Odin should put you in charge of the kitchens of Valhalla.", "Word is you've never burned a single sausage, {player}. Not one!", "Every Viking fights better on a full belly, and you fill them best of all." } },
			{ "skill/Farming", new[] { "They say anything grows where you plant it, {player}. Even in the rocks.", "A master farmer! Carrots, turnips, barley - the soil loves you.", "Word is your fields could feed every village in the land.", "Freyr must walk your rows at night. Nobody else grows crops like yours." } },
			{ "skill/Crafting", new[] { "They say everything you make comes out finer than the last, {player}.", "A master crafter! Your workbench must be the busiest in the land.", "Word is your gear never seems to wear out. That's craftsmanship.", "Even the dvergr would trade their secrets for a look at your workbench." } },
			{ "skill/Dodge", new[] { "They say no blow has landed on you in a moon, {player}. Is that true?", "A master of the roll! You tumble through a fight and come up smiling.", "Word is the trolls swing at you and hit nothing but air.", "Can't hit what isn't there - and you've made that an art." } },
			{ "skill/Ride", new[] { "They say you ride a lox like you were born in the saddle, {player}.", "A master rider, {player}! Most of us just hold on and pray to Odin.", "Word is your lox knows where you want to go before you do.", "Thundering across the plains on a lox - now that's how a Viking travels!" } },
			{ "allskills", new[] { "Every skill, mastered? There isn't a Viking alive who can say that, {player}. Until you.", "Blade, bow, staff, plow and pot - is there anything you can't do?", "The skalds will need a whole winter to sing all your songs.", "Odin himself must have sent a raven to ask how you did it.", "I'm good at one thing, maybe two, {player}. You've mastered them all. I'll drink to that!" } },
			{ "achievement/ach_grindtrees", new[] { "Five hundred trees, {player}! Is there a forest left standing?", "They say you've felled more trees than this whole village put together.", "All that timber - you could build a longship for every Viking I know.", "The Greydwarves must have a name for you by now. Not a kind one, but still!" } },
			{ "achievement/ach_grindcook", new[] { "A hundred dishes cooked! Your hearth must never go cold, {player}.", "They say you've fed half the land by now. My belly is jealous.", "Next time you cook, {player}, save me a bowl. Just one. Maybe two.", "A Viking who can cook is worth two who can fight. You're worth a hundred." } },
			{ "achievement/ach_grindharvest", new[] { "Five hundred crops harvested! Your back must ache, {player}.", "They say your barns are fuller than a jarl's, {player}. Well earned!", "All those carrots and turnips - no one goes hungry near you.", "Sow, wait, reap, five hundred times over. That's patience worthy of a saga." } },
			{ "achievement/ach_grindforager", new[] { "Two hundred and fifty berries and as many mushrooms! Your basket must be bottomless, {player}.", "They say there's not a berry left on any bush in the meadows. Ha!", "Word is you can find mushrooms in the dark by smell alone.", "That many mushrooms, and you never once ate the wrong one? Wise, very wise." } },
			{ "achievement/ach_grindhoney", new[] { "Five hundred times you've robbed the bees, and they still let you near. Amazing, {player}.", "That's enough honey for mead to last ten winters. When's the feast?", "They say your bees hum your name. Well, they hum something.", "A beekeeper of legend! Sweet work, in every sense." } },
			{ "achievement/ach_grindeat", new[] { "Five hundred meals, {player}! No adventuring on an empty stomach for you.", "They say you eat like three Vikings. I mean that as praise!", "Five hundred meals and you still look forward to the next one. That's a true Viking.", "No wonder you're so strong - a full belly is half of every victory." } },
			{ "achievement/ach_killallcreatures", new[] { "Every kind of beast in the land has fallen to you, {player}. Every one!", "From the smallest neck to the biggest troll, you've faced them all.", "They say there's nothing left out there that doesn't run when it smells you.", "A hunter like you comes along once in a hundred winters. Well done!" } },
			{ "achievement/ach_findalltrophies", new[] { "Every trophy in the land! Your walls must be covered, {player}.", "Your trophy hall must tell the whole saga of your travels.", "All of them? Even the rare ones? You must be the luckiest hunter alive... or the most stubborn.", "Do you ever stop and look at them all, {player}? I would, every night." } },
			{ "achievement/ach_grindfish", new[] { "They say you've a hook and bait for every fish that swims, {player}. Clever!", "Some of those fish, most of us have never even heard of!", "You must have the patience of a mountain to catch every kind of fish.", "Which one fought the hardest? I want to hear the whole story!" } },
			{ "achievement/ach_bigfish", new[] { "A catch worthy of Njord himself, {player}! How big was it, really?", "They say it took you half the day to haul it in. I believe every word.", "I've fished all my life and never seen one that size. You must be blessed.", "Word is the whole village could eat for a week off that one fish." } },
			{ "achievement/ach_allweaponcraft", new[] { "Every kind of weapon, made by your own hands, {player}! Your forge must never cool.", "Swords, axes, bows, staffs - is there anything your anvil can't make?", "They say you could arm a whole war band from your own smithy.", "The dwarves who forged Mjolnir would want you at their anvil." } },
			{ "achievement/ach_allitemcraft", new[] { "Every item there is to make, and you've made them all, {player}. Astonishing!", "Is there a workbench, forge or table you haven't mastered? I doubt it.", "They say you can make anything from almost nothing. A true artisan.", "Clothes, tools, armor, trinkets - the whole land must be wearing your work." } },
			{ "achievement/ach_allfoodcooked", new[] { "Every dish in the land, cooked by your hand, {player}! What a feast that would make.", "From plain grilled neck tails to the fanciest pies - you've cooked them all.", "They say no recipe is a secret from you now.", "Name any dish and you've made it. I'll be at your table if you'll have me!" } },
			{ "achievement/ach_allfoodeaten", new[] { "Every kind of food in the land, {player}? Even the strange things from the swamp?", "They say you'll try anything once. Your stomach must be made of iron.", "What's the best thing you've ever eaten? You'd know better than anyone now.", "Next time I cook, I'd love your verdict. Be gentle, though!" } },
			{ "achievement/ach_builddyrnwyn", new[] { "Dyrnwyn, reforged in your hands! The legends were true, {player}.", "They say the blade blazes when a worthy hand draws it. Yours must burn bright!", "Every piece found and joined - the skalds will sing of that quest for ages.", "Some say Dyrnwyn chose you, not the other way around. I believe it." } },
			{ "achievement/ach_buildhigh", new[] { "They say your hall reaches up to the clouds, {player}!", "So tall! How do you keep it from falling down?", "Word is you can see half the world from the top of your tower.", "Mighty halls indeed! Even the jotunn would have to look up at it." } },
			{ "achievement/ach_buildhighworld", new[] { "Building on the top of the world itself, {player}! Doesn't the wind blow you off?", "They say you built so high the drakes fly below your floor.", "Up there, you must be closer to Asgard than any of us.", "All that stone and timber hauled up a mountain? Your legs must be iron." } },
			{ "achievement/ach_allbuildpieces", new[] { "Every piece there is to build, and you've built them all, {player}!", "Walls, roofs, stairs, beams - is there anything you can't put up?", "They say you could raise a whole village by yourself.", "A carpenter of legend! Come look at my roof sometime, {player} - it leaks." } },
			{ "achievement/ach_explorensew", new[] { "North, south, east and west - you've walked to the edges of the world, {player}!", "They say you've seen more of the land than every Viking here put together.", "What's out there at the far ends, {player}? Tell me everything over a mead!", "Every horizon, chased down. Odin the Wanderer would call you kin." } },
			{ "achievement/ach_grindsail", new[] { "Twice around the world by sail! Do you even remember what dry land feels like, {player}?", "They say you've spent more time at sea than the serpents.", "Word is the wind knows your sail by now and blows where you need it.", "Two whole trips around the world... I get seasick crossing a river." } },
			{ "achievement/ach_grindsailhelm", new[] { "All the way around the world with your own hand on the helm, {player}! A true captain.", "They say you've steered through every storm the sea can throw, and here you are!", "With a captain like you, I'd sail anywhere. Well... almost anywhere.", "Word is you can smell a storm coming a day away. That's a captain's nose." } },
			{ "achievement/ach_kingsqueens", new[] { "Viking, hunter, artisan, chef, carpenter and explorer - all of them, {player}? You're royalty!", "They say the land has crowned a new king or queen, and it's you. Shall I bow?", "The skalds can't decide which of your deeds to sing first, so they sing them all.", "When the jarls gather, they'll be asking for your advice now." } },
			{ "achievement/ach_childofodin", new[] { "Child of Odin! The All-Father himself claims you, {player}. What an honor.", "The toughest, the best hunter, a survivor and a pathfinder - what's left to prove?", "They say Odin's ravens follow you now, just to see what you do next.", "When your time comes, {player}, Valhalla's doors will open before you even knock." } },
			{ "achievement/ach_deathbytreeall", new[] { "Killed by every kind of tree, {player}? Are you sure you're all right?", "They say the trees have a feud with you. Maybe stand to one side when they fall?", "Every kind of tree? Once is an accident. That's... a lot of accidents.", "Next time you chop, I'll stand by and shout when it starts to fall. Deal?" } }
		};
	}
}
